/* Módulo 3: demonstração oficial + estudos da documentação. Exemplos e atividades autorais. */
(() => {
  const d=window.LEAP;
  const path=(section,name)=>'building-blocks/'+section+(name?'/'+name:'');
  const ref=(section,name)=>[name||section,path(section,name)];
  const ds=(section,name,title,text,observe,picture=false)=>({doc:path(section,name),title,text,observe,...(picture?{imagePath:'assets/docs/m3-'+name+'.png',caption:'Bloco '+name+' na documentação oficial. Imagem original; amplie para ler as propriedades.'}:{})});
  const q=(title,answer,other,why)=>({q:title,options:[answer,other],correct:0,why});
  const lessons=[
    {
      slug:'dados-fundamentos',title:'Um fluxo, vários conjuntos de dados',topic:'fontes',video:'V5r-Fovn_vs',originalLesson:'Demonstração Data Driven',duration:'1:20',read:'8 min',
      description:'Veja como uma planilha substitui valores fixos no cadastro e prepara a execução para vários registros.',
      objectives:['Separar ações do fluxo e dados de entrada.','Interpretar linhas, colunas e conectores azuis.','Distinguir a demonstração curta de um teste completo.'],
      concepts:[['Dados como entrada','Em vez de copiar um fluxo para cada cliente, uma fonte fornece os valores usados pela mesma sequência. Cada linha representa um conjunto de entradas relacionadas.'],['Execução e valores','As conexões verdes conduzem a execução. As azuis fornecem valores, como Name, Customer Group e Tax State. Uma conexão de dados não substitui a ordem das ações.'],['Cobertura com intenção','Mais linhas só ampliam a cobertura se representarem casos diferentes e tiverem resultados esperados. A demonstração apresenta parametrização, sem comprovar todas as combinações ou validações de negócio.']],
      flow:['Read Excel · linha','Name / Customer Group / Tax State','Campos do cadastro','Próxima linha'],flowNote:'Esquema da parametrização mostrada. O restante do cadastro já existia antes da demonstração.',
      steps:[{time:5,title:'Separe o roteiro dos valores',text:'Observe o fluxo de cadastro já existente. A mudança demonstrada é alimentar seus campos por uma planilha, sem reconstruir toda a navegação.',observe:'O vídeo tem cerca de 80 segundos; não é uma execução detalhada de todos os blocos do módulo.'},{time:26,image:30,title:'Escolha a planilha no Read Excel',text:'Adicione Read Excel e selecione o arquivo com os dados. O vídeo usa um arquivo de clientes no contexto de um cadastro já preparado.',observe:'O arquivo e a aplicação do vídeo não estão incluídos. Os arquivos oferecidos neste caderno são exemplos autorais fictícios.',caption:'Seleção do arquivo de dados no Read Excel.'},{time:36,image:45,title:'Defina o intervalo e exponha as colunas',text:'Selecione a região da planilha correspondente aos campos. As colunas passam a aparecer como saídas de dados para o restante do fluxo.',observe:'Confira a opção de cabeçalho para não tratar o nome da coluna como um cliente.',caption:'Intervalo selecionado e saídas Name, Customer Group e Tax State.'},{time:48,image:60,title:'Conecte os campos e escolha Iterate',text:'Leve cada coluna ao campo correspondente e observe a escolha de Iterate. Para um teste completo, acrescente verificação por registro e encerramento após a leitura.',observe:'A demonstração mostra a montagem. Ela não prova uma execução de centenas de clientes com resultados validados.',caption:'Conectores azuis e opções de seleção de linhas.',animation:{file:'dados-parametrizacao.gif',start:43,end:65,caption:'Acompanhe as conexões das colunas aos campos e a escolha de Iterate.'}}],
      pitfalls:[['Duplicar em vez de parametrizar','Cópias do roteiro dificultam corrigir a mesma operação em vários casos.'],['Quantidade sem resultado','Uma planilha grande não substitui uma expectativa clara para cada registro.']],
      exercise:{title:'Desenhe três clientes fictícios',tasks:['Separe as ações de cadastro dos três valores de entrada.','Escolha uma linha para cada cliente.','Defina uma evidência que comprove o cadastro de cada um.'],answer:'O roteiro permanece comum. Cada linha fornece nome, grupo e estado ao cadastro. A confirmação deve identificar o cliente daquela linha, e o caso só termina após as verificações previstas.'},
      practice:'Com Leapwork e uma aplicação de demonstração, comece com uma linha, confira o resultado e depois use Iterate com poucos registros fictícios.',
      quiz:[q('O que uma linha da planilha representa?','Um conjunto relacionado de entradas.','Uma cópia obrigatória de todos os blocos do fluxo.','Os dados mudam, enquanto o roteiro pode ser reutilizado.'),q('O vídeo comprova centenas de cadastros validados?','Não; apresenta a montagem da parametrização.','Sim, todo o módulo é executado nesses 80 segundos.','O alcance da demonstração é menor que uma validação completa do processo.')],docs:[ref('data-driven','read-excel'),ref('module-input-and-output','value-input')]
    },
    {
      slug:'dados-ler-excel',title:'Ler uma planilha com intervalo e iteração',topic:'fontes',read:'10 min',
      description:'Escolha origem, cabeçalhos e método de leitura para não misturar dados, índices e término da coleção.',
      objectives:['Distinguir Data File, Local Path e Cloud file.','Selecionar intervalo e cabeçalhos.','Separar a saída por linha de Completed e Not read.'],
      concepts:[['Origem da planilha','Data File mantém uma cópia no Leapwork; alterações exigem reenvio. Local Path referencia um caminho acessível à execução. Cloud file usa uma conexão configurada e depende da versão.'],['Contrato de colunas','Cabeçalhos nomeiam as saídas. Um intervalo que deixa fora as novas linhas não passa a incluí-las automaticamente só porque o arquivo cresceu.'],['Método de leitura','First row lê uma linha, Row index escolhe uma posição do intervalo e Iterate percorre as linhas. Completed representa o término; Not read trata falha de leitura.']],
      flow:['Read Excel · Iterate','Valores da linha → operação','Verificar registro','Completed → concluir'],flowNote:'A saída de execução por linha é distinta de Completed. O desenho não exige um Loop adicional para o mesmo intervalo.',
      steps:[ds('data-driven','read-excel','Defina a origem e o acesso','Use o arquivo fictício disponibilizado no laboratório ou uma planilha de testes. Em Local Path, confirme o caminho no Agent; em Data File, envie a versão correta.','Cloud file requer conexão SharePoint e permissões próprias, não disponíveis automaticamente no caderno.',true),ds('data-driven','read-excel','Escolha o intervalo e os cabeçalhos','Em Define range, escolha a planilha e a região. Use a primeira linha como cabeçalho quando ela contiver os nomes das colunas.','Não inclua linhas em branco ou cabeçalhos como registros sem intenção.'),ds('data-driven','read-excel','Mapeie as colunas e teste uma linha','Conecte as saídas aos campos ou Value Inputs correspondentes. Valide o mapeamento com uma linha antes de habilitar Iterate.','Nome, quantidade e preço não devem ser ligados apenas por proximidade visual.'),ds('data-driven','read-excel','Percorra e trate a conclusão','Use Iterate, verifique o resultado de cada linha e siga de Completed para a conclusão. Trate Not read com um diagnóstico da origem.','Pass após a primeira linha pode encerrar o caso antes das demais.')],
      pitfalls:[['Arquivo atualizado, cópia antiga','Data File não acompanha edições externas sem novo envio.'],['Término prematuro','Completed e a saída por linha têm responsabilidades diferentes.']],
      exercise:{title:'Rastreie duas linhas',tasks:['Defina três cabeçalhos.','Mapeie duas linhas aos campos.','Indique os caminhos de leitura, conclusão e falha.'],answer:'Cada linha fornece seus valores à operação. Completed continua após a coleção; Not read trata arquivo ausente ou leitura impossível. Os nomes dos campos devem corresponder ao contrato da planilha.'},
      practice:'Use a planilha autoral do laboratório e confira cabeçalhos, quantidade de linhas e comportamento com caminho inexistente.',
      quiz:[q('Editar o arquivo original atualiza automaticamente Data File?','Não; a cópia precisa ser reenviada.','Sim, ele sempre permanece sincronizado.','Data File é uma cópia armazenada.'),q('Qual saída sinaliza todas as linhas processadas?','Completed.','A saída que executa uma vez por linha.','A conclusão da coleção é separada de cada item.')],docs:[ref('data-driven','read-excel')]
    },
    {
      slug:'dados-escrever-excel',title:'Escrever resultados no Excel',topic:'fontes',read:'9 min',
      description:'Registre resultados por coluna, escolhendo entre uma linha específica e o acréscimo de um novo registro.',
      objectives:['Mapear colunas de saída.','Distinguir Row index e Append.','Verificar a gravação e tratar Not written.'],
      concepts:[['Arquivo de saída','Write Excel trabalha sobre um arquivo e intervalo definidos. Prepare uma cópia de testes com cabeçalhos, sem presumir que todo arquivo será criado automaticamente.'],['Posição ou acréscimo','Row index escreve em uma linha do intervalo; Append acrescenta na primeira linha vazia após os dados. Reexecutar Append pode duplicar resultados.'],['Formato e evidência','Auto-apply formatting pode aplicar formatos conforme os tipos; desabilitado, os valores são escritos como texto. Confira os dados gravados, não apenas a ausência de erro.']],
      flow:['Resultado do registro','Write Excel · colunas mapeadas','Conferir gravação','Not written → tratar'],flowNote:'A gravação do relatório é distinta da operação que produziu o resultado de teste.',
      steps:[ds('data-driven','write-excel','Prepare o arquivo de saída','Crie uma cópia da planilha de resultados do laboratório, selecione Local path ou a conexão Cloud file disponível e defina o intervalo.','O usuário do Agent precisa ter acesso de escrita.',true),ds('data-driven','write-excel','Escolha o método de escrita','Use Row index quando a posição for parte do contrato, ou Append para acrescentar um registro. Mapeie ID, resultado e motivo às colunas.','O índice é relativo ao intervalo definido, não necessariamente à linha absoluta da planilha.'),ds('data-driven','write-excel','Confira os tipos e a formatação','Escolha conscientemente Auto-apply formatting. Mantenha códigos que exigem zeros à esquerda como texto e valores de cálculo como números.','Exibir 001 como 1 pode mudar a identidade de um código.'),ds('data-driven','write-excel','Releia uma amostra e trate a falha','Após escrever, confira a linha no arquivo ou com Read Excel. Ligue Not written ao tratamento apropriado.','Um arquivo aberto com bloqueio ou um caminho incorreto pode impedir a gravação.')],
      pitfalls:[['Append duplicado','Reexecuções podem acrescentar o mesmo registro outra vez.'],['Sobrescrita','Um Row index incorreto pode substituir um resultado anterior.']],
      exercise:{title:'Escolha um relatório rastreável',tasks:['Defina um identificador por registro.','Escolha Append ou índice e justifique.','Descreva como conferir uma linha gravada.'],answer:'Use um ID estável junto de resultado e motivo. Append atende a um histórico, enquanto índice exige uma correspondência conhecida. Releia os valores para confirmar a escrita.'},
      practice:'Escreva apenas em uma cópia do arquivo de testes e confira a reexecução para identificar duplicatas ou substituições.',
      quiz:[q('Append impede duplicatas automaticamente?','Não; é preciso definir uma política de identificação.','Sim, ele deduplica qualquer resultado.','Acrescentar linhas não equivale a deduplicar.'),q('O que verificar além do bloco concluir?','Os valores gravados nas colunas corretas.','Apenas o nome do bloco.','A evidência deve confirmar o relatório produzido.')],docs:[ref('data-driven','write-excel'),ref('data-driven','read-excel')]
    },
    {
      slug:'dados-banco',title:'Usar dados de um banco por ODBC',topic:'fontes',read:'10 min',
      description:'Prepare uma consulta de leitura, entenda onde a conexão deve existir e trate registros vazios ou nulos.',
      objectives:['Identificar os pré-requisitos da conexão no Agent.','Distinguir consulta, colunas e método de retorno.','Validar resultado, vazio e erro.'],
      concepts:[['Conexão de execução','Database usa uma conexão ODBC configurada no computador da execução. Driver, DSN e permissões precisam existir nesse ambiente.'],['Consulta como contrato','Selecione apenas as colunas necessárias e defina a ordenação quando ela importar. Inserir texto por token não transforma automaticamente a consulta em um comando parametrizado seguro.'],['Vazio não é zero','Uma consulta sem linhas, um campo NULL e um valor numérico zero são estados diferentes. Defina a expectativa de cada um.']],
      flow:['Database · consulta de leitura','Colunas → operação','Verificar registros','Error → diagnóstico'],flowNote:'O exemplo didático propõe leitura de uma base fictícia; nenhuma conexão real é aberta pelo caderno.',
      steps:[ds('data-driven','database','Prepare uma conexão de testes','Configure o ODBC no Agent e confirme acesso de leitura à base de demonstração. Indique a conexão no bloco.','Uma configuração existente apenas no computador de edição não basta.',true),ds('data-driven','database','Defina consulta e colunas','Use uma consulta de leitura sobre dados fictícios e confira os nomes retornados. Refresh executa a consulta; a documentação alerta para restrições quando Query contém campos dinâmicos.','Não use Refresh como se fosse uma inspeção sem execução da consulta.'),ds('data-driven','database','Escolha o retorno e trate os dados','Escolha Method de acordo com a necessidade e mapeie as colunas. Confira quantidade de linhas e a configuração Handle NULL values.','Não confunda NULL, texto vazio e zero nos casos de teste.'),ds('data-driven','database','Valide a resposta antes de continuar','Examine os dados e Error. Confira também o comportamento de timeout da versão usada; a saída normal não substitui uma condição explícita de resultado válido.','Registre diagnóstico sem expor credenciais de conexão.')],
      pitfalls:[['Consulta montada com entrada livre','Concatenação de texto pode alterar a consulta; não trate token como parâmetro SQL protegido.'],['Resultado vazio aprovado','A conclusão da consulta não prova que os registros esperados foram retornados.']],
      exercise:{title:'Descreva um contrato de consulta',tasks:['Escolha ID e duas colunas necessárias.','Defina o resultado esperado e um caso vazio.','Indique onde a conexão precisa estar configurada.'],answer:'O contrato especifica colunas, registros e tratamento de vazio. O ODBC deve existir no Agent. Valide o resultado antes de usá-lo no fluxo.'},
      practice:'Com acesso a uma base descartável, use uma conta de leitura e compare retorno esperado, vazio e NULL. O caderno não fornece servidor nem conexão.',
      quiz:[q('Onde o ODBC precisa funcionar?','No computador em que o caso é executado.','Somente no navegador do caderno.','O Agent executa a consulta.'),q('Uma consulta terminada prova que há registros corretos?','Não; valide conteúdo e quantidade.','Sim, toda conclusão implica dados corretos.','Execução e resultado são verificações distintas.')],docs:[ref('data-driven','database')]
    },
    {
      slug:'dados-http',title:'Consultar uma API e validar sua resposta',topic:'fontes',read:'10 min',
      description:'Separe falha de transporte, código HTTP e conteúdo retornado antes de usar os dados em um teste.',
      objectives:['Escolher método, URL e cabeçalhos.','Distinguir Failed e Response Code.','Validar o contrato do corpo da resposta.'],
      concepts:[['Requisição e resposta','HTTP Request envia uma chamada e expõe código, cabeçalhos, corpo e tempo. A execução do bloco não representa automaticamente aprovação do cenário.'],['Transporte e protocolo','Failed é documentado para situações sem código HTTP, como conexão indisponível. Uma resposta 404 ou 500 ainda possui código e precisa de uma validação explícita.'],['Corpo não é objeto automático','Receber texto JSON não garante que seus campos tenham sido interpretados. Faça a extração apropriada e valide presença, tipo e significado dos valores.']],
      flow:['HTTP Request','Response Code → Compare','Response Body → leitura validada','Dados → operação'],flowNote:'É um roteiro autoral baseado na documentação. O JSON local do laboratório é uma amostra, não uma chamada real.',
      steps:[ds('data-driven','http-request','Defina uma chamada de leitura controlada','Comece por GET em um endpoint de testes. Configure URL e cabeçalhos conforme o contrato. A documentação descreve Headers como uma lista delimitada por ponto e vírgula.','Não converta o exercício em uma operação de criação ou exclusão sem um cenário preparado.'),ds('data-driven','http-request','Separe ausência de resposta e erro HTTP','Trate Failed para problemas sem código recebido. Compare Response Code com os códigos permitidos pelo caso.','Receber uma página de erro com código não equivale a falha de transporte.'),ds('data-driven','http-request','Leia o corpo com um contrato','Extraia os campos necessários por uma técnica adequada ao formato. Confira ID, tipos e campos obrigatórios antes de alimentar uma operação.','Um texto que contém o número 200 não prova que Response Code seja 200.'),ds('data-driven','http-request','Defina limites e evidências','Configure o timeout e registre código, ID e motivo da decisão. Preserve a validação de certificados; Accept certificate altera a verificação de confiança.','Não desabilite validação de certificado apenas para esconder uma configuração incorreta.')],
      pitfalls:[['Código sem conteúdo','Um 200 pode retornar um corpo que não atende ao contrato.'],['Timeout como sucesso','A documentação descreve conclusão do bloco também em situações de erro; valide os resultados.']],
      exercise:{title:'Classifique três respostas',tasks:['Classifique conexão indisponível.','Classifique HTTP 404 com corpo.','Classifique HTTP 200 com campo obrigatório ausente.'],answer:'A primeira é falha de transporte sem resposta; a segunda é resposta HTTP com código não permitido no exemplo; a terceira passa no código, mas falha no contrato do corpo.'},
      practice:'Use um endpoint de testes ou mock preparado no seu ambiente. O caderno oferece uma resposta fictícia para estudo, sem fazer chamadas externas.',
      quiz:[q('HTTP 500 necessariamente aciona Failed por falta de resposta?','Não; há resposta com um código que deve ser validado.','Sim, todo código diferente de 200 significa ausência de resposta.','Falha de transporte e erro HTTP são situações diferentes.'),q('Um código 200 basta para aprovar todo contrato?','Não; valide os dados do corpo.','Sim, o conteúdo é sempre correto.','Código e conteúdo são camadas distintas de verificação.')],docs:[ref('data-driven','http-request'),ref('logic','compare')]
    },
    {
      slug:'dados-arquivos',title:'Fornecer, compactar e guardar arquivos',topic:'fontes',read:'9 min',
      description:'Acompanhe o arquivo como dado entre Set File, Compress File e Save File, com tratamento de falhas.',
      objectives:['Distinguir arquivo de caminho textual.','Encadear as saídas File e Zip File.','Localizar a evidência salva pelo Leapwork.'],
      concepts:[['Fornecer um arquivo','Set File disponibiliza um arquivo para outros blocos. O texto de um caminho e o objeto de arquivo transportado pelo conector não são conceitos intercambiáveis.'],['Compactar','Compress File recebe arquivos e produz um ZIP. A página específica documenta compactação; o caderno não presume uma ação de descompactar ausente dessa referência.'],['Guardar evidência','Save File recebe conteúdo de arquivo e o armazena sob gerenciamento do Leapwork. A versão consultada não exige escolher livremente um caminho manual no bloco.']],
      flow:['Set File','Compress File → Zip File','Save File','Conferir artefato'],flowNote:'Esquema autoral. Verifique as saídas Failed e Not saved em cada etapa, em vez de usar só o caminho normal.',
      steps:[ds('data-driven','set-file','Forneça os arquivos de teste','Selecione arquivos fictícios via Source type compatível e confirme a saída File.','O formato e a origem precisam ser aceitos pela versão usada.',true),ds('data-driven','compress-file','Monte o pacote de arquivos','Adicione as entradas a Files e forneça Zip File ao próximo bloco. Confira os limites documentados e trate Failed.','Empacotar não valida automaticamente o conteúdo dos arquivos.',true),ds('data-driven','save-file','Guarde o pacote como evidência','Ligue o arquivo ao File Input de Save File e trate Not saved. Consulte o arquivo gerenciado na evidência da execução.','Não invente uma propriedade de caminho de saída inexistente no bloco consultado.',true),ds('data-driven','save-file','Confira o artefato produzido','Recupere o arquivo pelo painel de mídia ou relatório e confira nome, tamanho e conteúdo esperado do pacote.','Um arquivo existente de outra execução não comprova a produção atual.')],
      pitfalls:[['Objeto e caminho confundidos','Conectar um nome textual não garante fornecer o arquivo pretendido.'],['Operação não demonstrada','A referência específica de Compress File descreve criação de ZIP, não todas as operações possíveis com arquivos compactados.']],
      exercise:{title:'Desenhe um pacote de evidências',tasks:['Escolha dois arquivos fictícios.','Indique o dado recebido por cada bloco.','Defina a conferência do ZIP final.'],answer:'Set File fornece arquivos; Compress File gera Zip File; Save File guarda o artefato. Confira se o pacote final contém os dois arquivos desta execução.'},
      practice:'Use arquivos descartáveis pequenos e recupere o resultado salvo na mídia da execução. Não altere evidências antigas para simular sucesso.',
      quiz:[q('O texto de um caminho é sempre igual ao dado File?','Não; são representações e contratos diferentes.','Sim, todo bloco os trata como a mesma coisa.','O conector deve receber o tipo esperado.'),q('Save File exige um caminho manual na referência consultada?','Não; o armazenamento é gerenciado pelo Leapwork.','Sim, esse é o único parâmetro documentado.','A página especifica File Input e gerenciamento do artefato.')],docs:[ref('data-driven','set-file'),ref('data-driven','compress-file'),ref('data-driven','save-file')]
    },
    {
      slug:'dados-command-line',title:'Consumir a saída de um comando',topic:'fontes',read:'9 min',
      description:'Trate saída textual, código de retorno e iteração por linha como partes separadas de um contrato.',
      objectives:['Definir comando e pasta de trabalho.','Interpretar Return code.','Distinguir texto combinado e Iterate.'],
      concepts:[['Ambiente do processo','O comando roda no ambiente de execução, com ferramentas, pasta e usuário disponíveis ali. O caderno não executa comandos por abrir esta aula.'],['Contrato de saída','Text result e Return code respondem a perguntas diferentes: o que foi retornado e como o processo terminou. Zero é uma convenção comum, mas o contrato da ferramenta decide.'],['Linhas de saída','Get as text retorna um texto combinado; Iterate fornece linhas individualmente e Completed indica o fim. Logs misturados aos dados exigem filtragem deliberada.']],
      flow:['Command-line','Return code → decisão','Text result / Current line → leitura','Completed quando houver iteração'],flowNote:'O roteiro de estudo não dispara nenhum processo no computador.',
      steps:[ds('data-driven','command-line','Defina uma operação simples de testes','Escolha um comando de leitura ou emissão de texto preparado no ambiente e uma Working folder conhecida. Use o usuário de execução apropriado.','Não dependa de ferramentas ausentes no Agent.',true),ds('data-driven','command-line','Escolha o método de retorno','Use Get as text para analisar uma resposta inteira ou Iterate quando cada linha representar um item.','Uma quebra de linha em mensagem de log não se torna automaticamente um registro de negócio.'),ds('data-driven','command-line','Valide código e conteúdo','Confira Return code e Error occurred; depois valide a saída esperada. Defina o limite de tempo da operação.','A documentação alerta para comportamento de conclusão ao atingir timeout; não aprove só pela saída normal.'),ds('data-driven','command-line','Registre a evidência e conclua','Em Iterate, processe as linhas válidas e continue de Completed. Registre código e motivo sem expor argumentos sensíveis.','Texto vazio precisa de uma regra explícita, e não de uma aprovação automática.')],
      pitfalls:[['Saída misturada','Mensagens informativas podem contaminar dados destinados ao próximo bloco.'],['Argumentos livres','Não monte comandos arbitrários com conteúdo não validado das linhas de teste.']],
      exercise:{title:'Descreva uma ferramenta de leitura',tasks:['Defina o formato da saída.','Escolha os códigos permitidos.','Decida o comportamento para resposta vazia.'],answer:'O contrato informa formato, códigos e tratamento do vazio. Valide o código antes de interpretar o texto e separe logs dos dados de entrada.'},
      practice:'Use um comando inofensivo preparado no seu ambiente e compare saída válida, vazia e código de falha.',
      quiz:[q('Ter texto na saída prova sucesso do processo?','Não; confira também Return code e contrato.','Sim, qualquer texto é um resultado aprovado.','Uma mensagem pode descrever um erro.'),q('O que Completed representa em Iterate?','O fim do processamento das linhas retornadas.','A execução da primeira linha apenas.','A conclusão da coleção é distinta de cada linha.')],docs:[ref('data-driven','command-line')]
    },
    {
      slug:'dados-email',title:'Preparar uma notificação por e-mail',topic:'fontes',read:'8 min',
      description:'Entenda destinatário, assunto, corpo e anexos sem confundir envio aceito com recebimento verificado.',
      objectives:['Identificar a conexão de e-mail necessária.','Compor uma mensagem com dados do caso.','Tratar Could not send e a evidência de entrega.'],
      concepts:[['Conexão prévia','Send E-Mail depende de uma conexão configurada e funcional nas configurações de e-mail. Ele não usa automaticamente uma aba de webmail aberta.'],['Mensagem rastreável','Inclua o identificador da execução no assunto ou corpo quando precisar relacionar envio e resultado. Use apenas destinatários de teste na prática.'],['Envio e recebimento','A conclusão do bloco sinaliza a operação de envio conforme o ambiente. A chegada à caixa e o conteúdo recebido precisam de verificação própria quando fizerem parte da regra.']],
      flow:['Dados do caso','Send E-Mail · mensagem de teste','Could not send → tratar','Verificar recebimento, se exigido'],flowNote:'Nenhum e-mail é enviado pelo caderno. O cenário é uma preparação de prática futura.',
      steps:[ds('data-driven','send-e-mail','Prepare conexão e destinatários de teste','Confira a configuração de e-mail no Leapwork e defina uma caixa de testes que possa receber a mensagem.','O caderno não fornece servidor, conta nem credenciais.',true),ds('data-driven','send-e-mail','Mapeie assunto e corpo','Forneça To, Subject e Body. Use tokens para incluir ID e resultado sem divulgar dados sensíveis.','Confira cada destinatário antes de executar o fluxo no programa.'),ds('data-driven','send-e-mail','Adicione anexos quando previstos','Forneça arquivos de teste aos anexos disponíveis na versão utilizada e trate Could not send.','Um nome de arquivo não substitui um anexo real.'),ds('data-driven','send-e-mail','Defina a evidência de entrega','Se o requisito incluir recebimento, consulte a caixa de teste por um mecanismo preparado e compare ID e conteúdo.','Envio e recebimento são verificações separadas.')],
      pitfalls:[['Caixa incorreta','Uma notificação com dados fictícios ainda precisa de destinatário controlado.'],['Entrega presumida','Operação de envio concluída não comprova toda a cadeia de recebimento.']],
      exercise:{title:'Desenhe uma mensagem de teste',tasks:['Escolha um ID de execução fictício.','Defina assunto e destinatário controlado.','Indique uma evidência de chegada à caixa.'],answer:'Inclua um ID distinguível na mensagem e procure esse mesmo ID na caixa de testes. Trate falha de envio e ausência de recebimento como estados próprios.'},
      practice:'Só execute depois de configurar uma conexão e destinatários de testes. Esta aula, por si, não envia mensagens.',
      quiz:[q('O caderno envia a mensagem ao abrir a aula?','Não; apenas apresenta o estudo e a preparação.','Sim, usa sua conta automaticamente.','Não há conexão de e-mail configurada pelo caderno.'),q('Envio concluído e recebimento são a mesma evidência?','Não; podem exigir verificações separadas.','Sim, sempre coincidem.','A regra determina qual parte da cadeia deve ser confirmada.')],docs:[ref('data-driven','send-e-mail'),ref('data-driven','set-file')]
    }
    ,{
      slug:'dados-decisoes',title:'Comparar valores e escolher caminhos',topic:'logica',read:'9 min',
      description:'Escolha entre Compare e Switch e modele explicitamente os casos falsos ou sem correspondência.',
      objectives:['Comparar valores com o tipo correto.','Usar Switch para alternativas nomeadas.','Tratar Incorrect e No match.'],
      concepts:[['Duas alternativas','Compare avalia uma relação entre dois valores e oferece um caminho para a condição verdadeira e Incorrect para a falsa. O tipo da comparação influencia o resultado.'],['Várias alternativas','Switch recebe Input e segue o primeiro caso que corresponda à configuração. No match trata os valores que nenhum caso reconhece.'],['Valor e regra','O exemplo autoral usa Status = APROVADO, REJEITADO ou PENDENTE. Um texto desconhecido não deve ser tratado silenciosamente como aprovação.']],
      flow:['Status → Switch','APROVADO / REJEITADO / PENDENTE','No match → diagnóstico'],flowNote:'Compare e Switch são alternativas conforme a decisão. O esquema não representa um fluxo importável.',
      steps:[ds('logic','compare','Defina a relação e o tipo','Para um limite numérico, forneça dois números, escolha a relação e confira Comparison type. Teste o valor abaixo, igual e acima do limite.','Comparação textual e numérica podem produzir resultados diferentes.',true),ds('logic','switch','Configure uma decisão por status','Forneça Input, adicione os casos esperados e defina a comparação. Use a imagem do Switch para distinguir seus campos dos campos de Compare.','A página consultada de Switch contém descrições copiadas de Compare; o resumo inicial e a imagem mostram Input, Add case e No match.',true),ds('logic','switch','Trate o valor não reconhecido','Conecte No match a um diagnóstico ou resultado definido. Confira a ordem quando mais de um critério puder corresponder.','O bloco segue o primeiro caso correspondente, não todos ao mesmo tempo.'),ds('logic','compare','Confira os dois resultados','Execute casos verdadeiros, falsos e desconhecidos. Registre valor recebido, regra e caminho tomado.','Não ligue todos os caminhos a Pass se a regra exige rejeitar algum deles.')],
      pitfalls:[['Tipo errado','Comparar preço como texto pode expressar outra relação.'],['Caso desconhecido aprovado','No match deve ter uma regra explícita.']],
      exercise:{title:'Classifique quatro status',tasks:['Defina caminhos para APROVADO, REJEITADO e PENDENTE.','Acrescente o valor DESCONHECIDO.','Escolha o resultado de No match.'],answer:'Os três valores conhecidos seguem seus casos. DESCONHECIDO segue No match e exige diagnóstico ou rejeição definida, sem ser convertido silenciosamente em aprovação.'},
      practice:'Use valores fixos primeiro, depois forneça a coluna de status de uma planilha fictícia.',
      quiz:[q('Switch executa todos os casos que correspondem?','Não; segue o primeiro caso correspondente.','Sim, todos os caminhos sempre executam.','A ordem pode afetar critérios sobrepostos.'),q('Qual caminho trata um valor desconhecido no Switch?','No match.','Aprovação automática.','O valor sem correspondência precisa de tratamento próprio.')],docs:[ref('logic','compare'),ref('logic','switch')]
    },
    {
      slug:'dados-loops',title:'Controlar repetições e interrupções',topic:'logica',read:'10 min',
      description:'Defina os valores visitados por Loop e entenda como Break Iteration leva ao término da iteração.',
      objectives:['Calcular a sequência de Minimum, Maximum e Step.','Distinguir Current value e Completed.','Definir o alcance de Break Iteration.'],
      concepts:[['Limites inclusivos','Loop começa em Minimum e avança por Step sem ultrapassar Maximum. De 1 a 10 com passo 4, os valores são 1, 5 e 9.'],['Fim da coleção','Completed representa o término da iteração, mas isso não prova sozinho que todos os itens desejados foram processados: uma interrupção antecipada também pode chegar à conclusão.'],['Interrupção deliberada','Break Iteration interrompe a iteração em curso e aciona a conclusão do bloco iterador. Scope distingue o nível atual de todas as iterações aninhadas. Não o trate automaticamente como um simples continue.']],
      flow:['Loop · valores previstos','Operação por item','Condição de parada → Break Iteration','Completed → conferir resultado'],flowNote:'Uma condição de busca pode parar cedo; uma regra de processar todos os registros não deve perder itens silenciosamente.',
      steps:[ds('logic','loop','Escreva a sequência antes de configurar','Defina Minimum, Maximum e Step e anote os valores esperados. Use Current value como dado da operação.','Não presuma que o último valor será Maximum quando o passo não divide o intervalo.',true),ds('logic','loop','Separe item e conclusão','Ligue a operação à saída por iteração e o encerramento à saída Completed. Registre quantos itens foram realmente tratados.','A presença de Completed não substitui uma conferência de quantidade.'),ds('logic','break-iteration','Configure uma condição de interrupção','Quando uma regra permitir parar, acrescente Break Iteration e escolha Scope de acordo com o nível que deve terminar.','All pode encerrar iterações aninhadas além da atual.',true),ds('logic','loop','Teste término normal e antecipado','Compare uma execução completa com outra que para ao encontrar um alvo. Verifique contagem e evidência da condição de parada.','Pass após interrupção só é correto se a regra permitir esse término.')],
      pitfalls:[['Pass por item','Um terminal dentro da repetição pode acabar com o caso cedo demais.'],['Break como continue','A interrupção leva ao término previsto pelo iterador; confirme o alcance configurado.']],
      exercise:{title:'Conte as iterações',tasks:['Liste Loop de 1 a 10 com Step 4.','Indique o que muda se parar no valor 5.','Defina a evidência que distingue os dois casos.'],answer:'Sem interrupção, são 1, 5 e 9. Parando em 5, apenas 1 e 5 são tratados. Registre contagem e motivo; ambos podem chegar ao caminho de conclusão, mas não têm a mesma cobertura.'},
      practice:'Use dados fixos para observar cada valor e repita com uma condição de interrupção controlada.',
      quiz:[q('Quais valores aparecem de 1 a 10 com passo 4?','1, 5 e 9.','1, 4, 8 e 10.','O contador soma o passo e não ultrapassa o máximo.'),q('Completed prova que nunca houve interrupção?','Não; confira contagem e condição de parada.','Sim, sempre significa todos os itens originalmente previstos.','A conclusão pode acontecer após uma interrupção deliberada.')],docs:[ref('logic','loop'),ref('logic','break-iteration')]
    },
    {
      slug:'dados-calculos',title:'Calcular sem confundir texto e número',topic:'logica',read:'10 min',
      description:'Prepare números válidos, faça operações e defina uma política explícita de arredondamento.',
      objectives:['Usar Value A, Value B e Result number.','Distinguir bloco de valor e sequência de execução.','Conferir o arredondamento documentado.'],
      concepts:[['Entrada numérica','Um preço como 19,90 precisa ser interpretado segundo um formato conhecido. Trocar todo sinal de pontuação indiscriminadamente pode transformar o valor.'],['Cálculo por dados','Calculate recebe dois valores e produz Result number. Ele não tem conectores verdes de execução no cabeçalho; o consumidor usa o resultado calculado.'],['Arredondamento','A documentação especifica arredondamento de pontos médios para o par mais próximo. A regra de negócio pode exigir outra política; não presuma que todo arredondamento seja igual.']],
      flow:['Quantidade × preço → subtotal','Subtotal × fator → total','Result number → consumidor','Comparar com expectativa'],flowNote:'As etapas de Calculate são dependências de dados, não uma cadeia de conectores verdes entre cálculos.',
      steps:[ds('logic','calculate','Defina os números e suas unidades','Escolha quantidade, preço unitário e formato de entrada. Rejeite texto inválido e defina a unidade, por exemplo reais ou centavos.','Preço e quantidade não devem ser concatenados como texto.',true),ds('logic','calculate','Monte as operações por dependência','Configure Value A, Value B e Calculation method. Para duas operações, conecte o resultado da primeira à entrada da segunda.','Não procure um conector verde no Calculate.'),ds('logic','calculate','Confira a política de arredondamento','Configure Round result e Round decimals quando aplicável. Teste os pontos médios com a política documentada e com a regra exigida.','Na referência, 4,45 com uma casa vai para 4,4; não use uma suposição genérica de sempre arredondar para cima.'),ds('logic','calculate','Compare antes de aprovar','Forneça Result number a Compare ou a uma gravação de resultado. Defina tolerância, formato e comportamento para divisão por zero ou dado inválido.','Um resultado exibido com duas casas não comprova que toda a regra de cálculo foi validada.')],
      pitfalls:[['Formatação como cálculo','Exibir um número em moeda é diferente de executar a operação correta.'],['Políticas diferentes','Um laboratório em navegador pode usar outra política se ela não for implementada explicitamente.']],
      exercise:{title:'Faça um cálculo rastreável',tasks:['Calcule 2 × 19,90.','Aplique desconto autoral de 10%.','Defina a política de arredondamento para o resultado.'],answer:'O subtotal é 39,80 e o total com 10% é 35,82. A política de arredondamento deve ser definida antes de testar valores que gerem ponto médio.'},
      practice:'Valide valores simples e pontos médios separadamente. Compare o comportamento efetivo de Calculate com o contrato de negócio.',
      quiz:[q('Calculate tem cabeçalho com execução verde?','Não; fornece um resultado por conexão de dados.','Sim, exige uma sequência verde entre todos os cálculos.','Ele é consumido como transformação de valor.'),q('A referência usa qual política no ponto médio?','O par mais próximo.','Sempre o valor de maior magnitude.','A política documentada precisa ser considerada ao definir os testes.')],docs:[ref('logic','calculate'),ref('logic','compare')]
    },
    {
      slug:'dados-textos',title:'Normalizar texto e extrair padrões',topic:'logica',read:'10 min',
      description:'Combine operações simples de Change Text com uma expressão regular quando o contrato exigir um padrão.',
      objectives:['Escolher Trim, Replace, Concat ou outras operações simples.','Separar transformação de validação.','Tratar ausência e múltiplas correspondências em regex.'],
      concepts:[['Transformação simples','Change Text atende a operações como Trim, Replace, Concat e alteração de caixa. Ele fornece Result text sem conectores verdes no cabeçalho.'],['Padrão explícito','Regular Expression permite Match, Split e Replace. O padrão deve representar o contrato e incluir limites quando a intenção for validar o texto inteiro.'],['Normalizar sem esconder erro','Remover espaços externos pode ser permitido. Remover qualquer caractere que não se encaixa pode transformar um dado inválido em outro valor sem informar a falha.']],
      flow:['Texto bruto','Change Text · normalização permitida','Regular Expression · contrato','Resultado / Not found'],flowNote:'Change Text é uma transformação por dados; o esquema inclui também a decisão produzida pela validação.',
      steps:[ds('logic','change-text','Defina o que pode ser normalizado','Para um nome com espaços externos, escolha Trim e compare o resultado com o original. Use uma sequência de operações quando a regra exigir mais de uma.','Preserve o valor bruto para explicar o que foi alterado.'),ds('logic','regular-expression','Descreva o padrão esperado','No exemplo autoral de código PED-123, um padrão de texto inteiro pode ser ^PED-[0-9]{3}$. Escolha Method = Match para procurar o padrão.','Esse exemplo valida um formato simples, não a existência de um pedido real.',true),ds('logic','regular-expression','Trate zero e várias correspondências','Defina a ocorrência desejada ou All quando o objetivo for percorrer várias. Examine Count e Not found.','Encontrar um fragmento não valida automaticamente o texto inteiro.'),ds('logic','change-text','Compare entradas válidas e inválidas','Teste PED-123, texto extra e código com quantidade errada de dígitos. Confira transformação e validação como responsabilidades separadas.','Um resultado não vazio não prova que o contrato desejado foi atendido.')],
      pitfalls:[['Remoção excessiva','Limpar caracteres indiscriminadamente pode mascarar uma entrada errada.'],['Regex sem limites','Um fragmento válido dentro de lixo adicional pode satisfazer uma busca parcial.']],
      exercise:{title:'Valide um identificador simples',tasks:['Defina o formato PED seguido de hífen e três dígitos.','Escolha um exemplo válido e dois inválidos.','Explique o papel dos limites do padrão.'],answer:'PED-123 atende ao formato. PED-12 e textoPED-123extra não atendem ao contrato de texto inteiro. Os limites impedem aceitar apenas um fragmento.'},
      practice:'Teste o padrão com uma pequena tabela de entradas conhecidas e confira Count, resultado e Not found.',
      quiz:[q('Normalizar texto equivale a validar sua regra de negócio?','Não; são responsabilidades diferentes.','Sim, qualquer texto transformado é válido.','Uma transformação pode ser permitida sem confirmar todo o contrato.'),q('Por que delimitar um padrão de texto inteiro?','Para não aceitar apenas um fragmento dentro de outro texto.','Para eliminar a necessidade de casos negativos.','Os testes negativos continuam necessários.')],docs:[ref('logic','change-text'),ref('logic','regular-expression')]
    }
    ,{
      slug:'dados-datas',title:'Gerar datas e aplicar deslocamentos',topic:'estado',read:'9 min',
      description:'Distinga o relógio atual da execução de uma data-base fixa e calcule o deslocamento com unidades explícitas.',
      objectives:['Usar Generate date/time para o instante atual.','Distinguir Add, Subtract e Set.','Definir formato, fuso e fronteiras de calendário.'],
      concepts:[['Relógio da execução','Generate date/time fornece a data e hora atuais do sistema. Se o teste precisa de um instante fixo, defina uma data-base controlada em vez de presumir que o relógio ficará igual.'],['Deslocamento por valor','Offset Date/Time recebe a base e um deslocamento. Add soma, Subtract subtrai e Set altera componentes. O bloco entrega Result date/time sem execução verde no cabeçalho.'],['Calendário e apresentação','Mês não é sempre trinta dias. Ano, mudança de mês, horário e formato precisam ser escolhidos segundo o requisito; formatar uma data não muda automaticamente seu fuso.']],
      flow:['Data-base fixa ou Generate date/time','Offset Date/Time','Result date/time → verificação'],flowNote:'O gerador é acionado; Offset Date/Time é uma transformação por conexão de dados.',
      steps:[ds('generators','generate-date-time','Escolha entre agora e uma base fixa','Use o gerador quando a regra for relativa ao instante da execução. Para um caso reproduzível de calendário, forneça uma base explícita ao deslocamento.','Anote o fuso e o relógio do ambiente quando eles forem relevantes.',true),ds('logic','offset-date-time','Defina unidades e método','Configure Date/time to offset e os componentes do deslocamento. Escolha Add, Subtract ou Set de acordo com a intenção.','Set year não significa somar aquela quantidade de anos.',true),ds('logic','offset-date-time','Confira uma fronteira conhecida','No exemplo autoral, some um dia a 31/12/2026 e espere 01/01/2027. Compare datas como datas, não apenas textos em formatos distintos.','Teste separadamente fim de mês, ano bissexto e mudança de horário se fizerem parte da regra.'),ds('generators','generate-date-time','Registre base e resultado','Guarde a base usada e o valor calculado para explicar a comparação. Só formate para exibição na etapa apropriada.','Uma leitura posterior de agora pode produzir outro instante e alterar a comparação.')],
      pitfalls:[['Data atual variável','Um resultado esperado fixo pode falhar apenas porque o dia mudou.'],['Unidade inadequada','Somar um mês e somar trinta dias não são regras equivalentes.']],
      exercise:{title:'Cruze a virada do ano',tasks:['Defina 31/12/2026 como data-base.','Aplique Add de um dia.','Explique por que uma base fixa ajuda a revisar o caso.'],answer:'O resultado é 01/01/2027. A base fixa permite repetir a verificação independentemente do dia em que a aula for estudada.'},
      practice:'Teste bases fixas primeiro e depois compare com uma regra relativa ao relógio real do Agent.',
      quiz:[q('Generate date/time produz sempre a mesma base?','Não; usa a data e hora atuais do sistema.','Sim, repete a data da criação do fluxo.','O relógio muda e precisa fazer parte do contrato.'),q('Somar um mês equivale sempre a trinta dias?','Não.','Sim, em todo calendário.','A unidade deve corresponder à regra temporal exigida.')],docs:[ref('generators','generate-date-time'),ref('logic','offset-date-time')]
    },
    {
      slug:'dados-variaveis',title:'Guardar valores com o escopo correto',topic:'estado',read:'11 min',
      description:'Defina o nome, o alcance e a duração de uma variável antes de reutilizar seu valor.',
      objectives:['Distinguir Only this case, Schedule e Permanent.','Usar Set Variable antes da leitura.','Tratar valor ausente sem esconder o problema.'],
      concepts:[['Nome e escopo','Nomes diferenciam maiúsculas de minúsculas. Status e status são variáveis diferentes; o mesmo nome em escopos diferentes também representa valores distintos.'],['Duração do estado','Only this case/flow vale para a execução atual. Schedule compartilha valores dentro de uma execução da agenda. Permanent permanece entre execuções até ser alterado ou removido.'],['Leitura e ausência','Set Variable atualiza o valor por execução. Get Variable fornece Result value sem cabeçalho verde. A referência documenta uso de Default value quando a variável não existe; um fallback não prova que ela foi inicializada.']],
      flow:['Set Variable · nome + escopo','Get Variable · mesmo nome e escopo','Result value → consumidor'],flowNote:'Get Variable é uma leitura por conexão de dados. Não desenhe uma ligação verde a esse bloco.',
      steps:[ds('variables','set-variable','Escolha o alcance necessário','Para um acumulador de um caso, use Only this case/flow e inicialize em zero antes da repetição. Escolha Schedule ou Permanent apenas quando o compartilhamento for parte da regra.','Um valor permanente antigo pode contaminar uma nova execução.',true),ds('variables','get-variable','Leia a identidade exata','Configure o mesmo nome e escopo no Get Variable e conecte Result value ao consumidor.','Uma diferença de caixa ou escopo pode parecer perda de dados, mas é outra variável.',true),ds('variables','get-variable','Decida o comportamento de ausência','Defina Default value conscientemente e verifique o diagnóstico se a variável não existir. Para um dado obrigatório, não use um fallback que esconda a falta de inicialização.','Vazio não deve virar silenciosamente uma aprovação.'),ds('variables','set-variable','Confira atualização e concorrência','Quando houver acumulador, leia o valor atual, calcule e atualize na ordem certa. Se várias execuções compartilham estado, planeje isolamento; não presuma incremento atômico.','Conexões de dados não fornecem, sozinhas, uma garantia de exclusão entre casos concorrentes.')],
      pitfalls:[['Estado residual','Permanent mantém informações entre execuções.'],['Acumulador compartilhado','Atualizações concorrentes podem exigir outra estratégia de armazenamento ou isolamento.']],
      exercise:{title:'Escolha três escopos',tasks:['Escolha o escopo de um total de um caso.','Escolha o de um dado compartilhado na mesma execução de agenda.','Explique como tratar um valor obrigatório ausente.'],answer:'Use Only this case/flow para o total local e Schedule para o compartilhamento deliberado da mesma agenda. Um valor obrigatório ausente deve produzir diagnóstico, sem ser encoberto por um padrão conveniente.'},
      practice:'Crie uma variável local, atualize e leia. Depois compare com outro nome, caixa e escopo para entender a identidade.',
      quiz:[q('Status e status são o mesmo nome?','Não; os nomes diferenciam caixa.','Sim, sempre.','A identidade inclui o nome exato e o escopo.'),q('Default value comprova que a variável existia?','Não; pode ser apenas o fallback.','Sim, sempre confirma inicialização.','O valor padrão pode ocultar a ausência se não houver uma regra explícita.')],docs:[ref('variables','set-variable'),ref('variables','get-variable')]
    },
    {
      slug:'dados-geradores',title:'Gerar números e senhas de teste',topic:'estado',read:'9 min',
      description:'Combine dados dinâmicos com casos fixos, sem confundir aleatoriedade com cobertura ou unicidade.',
      objectives:['Definir intervalo, tipo e decimais de Generate Number.','Configurar os caracteres de Generate Password.','Guardar o dado produzido para repetir o diagnóstico.'],
      concepts:[['Intervalo controlado','Generate Number gera valores dentro dos limites inclusivos e permite filtrar pares, ímpares ou ambos e escolher decimais. Para uma sequência previsível, use uma estratégia de sequência, como Loop.'],['Senha de teste','Generate Password permite comprimento, maiúsculas, números e símbolos. Valide a política da aplicação, sem concluir que todas as restrições possíveis são cobertas por essas opções.'],['Diagnóstico reproduzível','Dados aleatórios podem repetir e deixar fronteiras sem teste. Combine exemplos fixos de limite com dados gerados e registre o necessário para compreender uma falha.']],
      flow:['Generate Number / Generate Password','Result value → operação de teste','Conferir política e resultado'],flowNote:'Os geradores são alternativas conforme o dado necessário. Este estudo não cria contas nem segredos de produção.',
      steps:[ds('generators','generate-number','Defina os limites numéricos','Escolha Minimum, Maximum, Type e Decimals. Prepare também valores fixos nos limites e fora deles quando a regra exigir rejeição.','Amostragem aleatória não garante visitar todos os valores.',true),ds('generators','generate-password','Configure uma senha fictícia','Defina Length e as opções de caracteres conforme a política do ambiente de testes. Forneça Result value ao campo apropriado.','Não use esse exemplo como avaliação de segurança de um gerador criptográfico.',true),ds('generators','generate-number','Separe identidade e aleatoriedade','Se o teste exige um ID único, acrescente um mecanismo de unicidade adequado. Não conte com um número aleatório isolado para impedir colisões.','Repetir uma amostra é possível.'),ds('generators','generate-password','Guarde evidências com cuidado','Registre configuração e identificador do caso. Se precisar reter um valor sensível de teste, use o mecanismo apropriado do ambiente, sem expô-lo indiscriminadamente nos logs.','Gerar um dado e provar que a aplicação o aceitou são etapas diferentes.')],
      pitfalls:[['Fronteiras não visitadas','Poucas amostras podem nunca alcançar mínimo ou máximo.'],['Unicidade presumida','Aleatoriedade não equivale a identificador sem colisões.']],
      exercise:{title:'Misture casos fixos e amostras',tasks:['Defina um intervalo permitido de 1 a 100.','Escolha casos fixos de fronteira e rejeição.','Explique o papel das amostras aleatórias.'],answer:'Use 1 e 100 como fronteiras e 0 e 101 como rejeições se essa for a regra. Amostras dentro do intervalo complementam esses casos, sem substituí-los nem garantir unicidade.'},
      practice:'Use dados fictícios em uma aplicação de testes e registre os casos suficientes para reproduzir uma falha.',
      quiz:[q('Um número aleatório é automaticamente único?','Não.','Sim, nunca se repete.','A geração pode produzir colisões.'),q('Amostras aleatórias substituem testes de fronteira?','Não; combine com valores fixos.','Sim, sempre visitam todos os limites.','A amostragem não garante cobertura completa.')],docs:[ref('generators','generate-number'),ref('generators','generate-password')]
    },
    {
      slug:'dados-clipboard',title:'Transferir texto pela área de transferência',topic:'apoio',read:'8 min',
      description:'Entenda o estado compartilhado do clipboard e compare seu uso com conexões diretas de dados.',
      objectives:['Distinguir Set Clipboard e Get Clipboard.','Garantir ordem e foco na colagem.','Evitar valor antigo como evidência nova.'],
      concepts:[['Estado da máquina','O clipboard é compartilhado com outras ações da sessão. Uma intervenção pode alterar o conteúdo entre escrita e leitura.'],['Escrever e ler','Set Clipboard define o texto com execução verde. Get Clipboard entrega Text por dados e não possui cabeçalho verde.'],['Alternativa direta','Quando o bloco de destino aceita um valor por conector, uma conexão direta pode evitar o estado intermediário do clipboard. Use a colagem quando fizer parte da interação necessária.']],
      flow:['Set Clipboard · texto de teste','Preparar foco e colar','Get Clipboard / leitura do destino','Comparar resultado'],flowNote:'O caderno não acessa nem modifica o clipboard do usuário ao abrir esta aula.',
      steps:[ds('logic','set-clipboard','Defina um texto fictício identificável','Escolha um valor que permita distinguir esta execução de conteúdo anterior e configure Set Clipboard.','Não use o clipboard pessoal como conjunto de dados de testes.',true),ds('logic','get-clipboard','Consuma o texto após a escrita','Use Get Clipboard como fonte de dados quando precisar conferir o valor. Se for colar, selecione e verifique o foco do campo de destino antes da ação de teclado.','Ler o clipboard não prova que o campo recebeu a colagem.',true),ds('logic','get-clipboard','Valide o destino correto','Leia o conteúdo do campo ou outra evidência depois da colagem e compare com o texto esperado.','O mesmo atalho pode atuar em outra janela se o foco mudar.'),ds('logic','set-clipboard','Planeje o isolamento','Evite interferência manual durante o ensaio e defina a limpeza de dados fictícios conforme seu ambiente. Compare a necessidade de clipboard com uma conexão direta.','A área de transferência não é um armazenamento privado por fluxo.')],
      pitfalls:[['Valor antigo','Uma leitura pode retornar conteúdo deixado por outra ação.'],['Destino incorreto','O clipboard pode estar certo, mas a colagem ter ocorrido em outro campo.']],
      exercise:{title:'Separe duas evidências',tasks:['Defina uma evidência de que o clipboard foi preenchido.','Defina outra de que o campo recebeu o texto.','Escolha quando dispensar o clipboard.'],answer:'Get Clipboard confere a fonte; a leitura do campo confere o destino. Uma conexão direta pode ser usada quando atende à intenção sem exigir copiar e colar.'},
      practice:'Em sessão de testes, use texto fictício e confira clipboard e destino separadamente.',
      quiz:[q('O clipboard é isolado automaticamente por fluxo?','Não; é estado compartilhado da sessão.','Sim, cada bloco tem um clipboard privado.','Outras ações podem interferir no conteúdo.'),q('Get Clipboard confirma que a colagem ocorreu no campo?','Não; leia também o destino.','Sim, a leitura já prova a colagem.','Fonte e destino são evidências distintas.')],docs:[ref('logic','set-clipboard'),ref('logic','get-clipboard')]
    },
    {
      slug:'dados-espera-janelas',title:'Usar esperas e preparar o estado das janelas',topic:'apoio',read:'8 min',
      description:'Reconheça o alcance de Wait e Close Windows antes de usá-los como preparação de um teste.',
      objectives:['Separar pausa de condição de prontidão.','Entender que Close Windows atua sobre todas as janelas.','Retomar as transformações de posição e área do módulo 1.'],
      concepts:[['Pausa fixa','Wait atrasa a execução pelo tempo definido. Isso não comprova que o elemento esperado existe nem que uma operação terminou.'],['Ação ampla','Close Windows fecha ou minimiza todas as janelas da área de trabalho conforme Action. Use apenas em um ambiente de testes preparado para esse alcance.'],['Coordenadas são valores','Offset Position e Offset Area calculam valores e já são estudados no módulo 1. Esses cálculos não movem objetos da aplicação.']],
      flow:['Preparar sessão de testes','Pausa, se necessária','Procurar evidência de prontidão','Prosseguir com contexto conhecido'],flowNote:'Close Windows é opcional e tem alcance amplo; não é uma etapa obrigatória de todo fluxo.',
      steps:[ds('logic','wait','Justifique a pausa','Use Wait quando o intervalo fizer parte da regra ou da observação. Para carregamento, procure uma condição que comprove prontidão.','Uma pausa longa pode esconder a falta de verificação.',true),ds('logic','close-windows','Confira o alcance antes da preparação','Se o roteiro realmente exigir fechar ou minimizar todas as janelas, escolha Action em uma sessão descartável e preparada.','Não use esse bloco para fechar apenas uma janela específica.',true),ds('logic','close-windows','Interprete a estabilidade visual','Await no movement aguarda a estabilidade de tela nas condições documentadas e tem um limite máximo. Isso não identifica por si só a página ou aplicação correta.','Uma tela imóvel pode continuar sendo a tela errada.'),ds('logic','offset-position','Retome posição e área como dados','Revise a aula de posições e áreas relativas do módulo 1. Passe o valor calculado à ação que realmente usará o ponto ou a região.','Offset Position não arrasta a imagem encontrada.',true)],
      pitfalls:[['Prontidão presumida','Passar um número de segundos não comprova o estado funcional.'],['Fechar tudo por engano','Close Windows tem uma abrangência maior que uma ação sobre uma janela específica.']],
      exercise:{title:'Escolha uma preparação proporcional',tasks:['Defina uma evidência de tela pronta.','Explique quando uma pausa é suficiente para a regra.','Diga por que Close Windows exige uma sessão preparada.'],answer:'Uma evidência de prontidão identifica o estado esperado. Wait só satisfaz regras que realmente pedem um intervalo. Close Windows afeta todas as janelas, então o ambiente deve permitir essa ação.'},
      practice:'Estude primeiro Wait e localização de prontidão. Só experimente Close Windows em uma sessão de testes sem documentos pessoais abertos.',
      quiz:[q('Wait prova que o carregamento terminou?','Não; é apenas uma pausa.','Sim, qualquer pausa garante prontidão.','A condição funcional precisa de evidência própria.'),q('Close Windows atua somente sobre uma janela capturada?','Não; a ação documentada alcança todas as janelas.','Sim, sempre fecha apenas um alvo específico.','O alcance deve ser considerado antes de usar o bloco.')],docs:[ref('logic','wait'),ref('logic','close-windows'),ref('logic','offset-position'),ref('logic','offset-area')]
    },
    {
      slug:'dados-csharp',title:'Reconhecer quando usar lógica C#',topic:'apoio',read:'9 min',
      description:'Planeje entradas, saídas e erros de uma extensão por código, sem presumir compatibilidade entre versões.',
      objectives:['Definir um contrato pequeno para a extensão.','Reconhecer campos, referências e tratamento de erro.','Distinguir o editor atual de exemplos antigos.'],
      concepts:[['Extensão delimitada','C# Code atende a uma transformação não conveniente com os blocos disponíveis. Antes de usá-lo, descreva entrada, resultado e falha sem depender de detalhes da interface.'],['Contrato do editor','A documentação atual descreve Source code, Fields e References. Os campos são disponibilizados por uma estrutura de dicionário e precisam de conversão de tipos apropriada.'],['Compatibilidade','A referência de C# mostra 2026.1, com .NET 8 e System Assemblies no lugar de GAC. As notas de versão 2026.3 anunciam .NET 10. Use o template e as dependências compatíveis com a instalação, sem estender o exemplo 2026.1 a toda versão posterior.']],
      flow:['Entradas tipadas','C# Code · transformação delimitada','Saída validada','Error occurred → tratar'],flowNote:'Esta aula prepara a extensão. Não apresenta um código supostamente executado sem a instalação do Leapwork.',
      steps:[ds('logic','c-sharp-code','Defina uma transformação pequena','Escolha, por exemplo, extrair um campo obrigatório de uma resposta JSON fictícia. Escreva o formato de entrada e o resultado esperado.','Não use regex como substituto genérico de um parser de JSON.',true),ds('logic','c-sharp-code','Use o template da versão instalada','Abra Click to edit e revise a entrada do template. Mapeie Fields e as conversões exigidas pelo contrato.','Não copie uma assinatura de outra versão como se fosse garantida.'),ds('logic','c-sharp-code','Confira as dependências','Use References conforme a versão. A página de C# consultada usa o contexto 2026.1 e descreve System Assemblies para .NET 8. As notas 2026.3 anunciam migração para .NET 10: confira o runtime da instalação antes de adicionar uma biblioteca externa.','A disponibilidade de uma DLL no seu computador não comprova sua disponibilidade no Agent.'),ds('logic','c-sharp-code','Teste sucesso e erro de formato','Use Run do editor para compilar e testar quando o programa estiver disponível. Confira o resultado e Error occurred com entradas inválidas e timeout.','Logs devem ajudar a entender o contrato sem publicar valores sensíveis.')],
      pitfalls:[['Assinatura inventada','O template e as dependências são específicos da instalação.'],['Erro ignorado','Uma exceção de parsing não deve virar um dado vazio aprovado.']],
      exercise:{title:'Escreva um contrato de parsing',tasks:['Defina um JSON fictício com ID.','Escolha o resultado se o campo existir.','Defina o comportamento para JSON inválido ou ID ausente.'],answer:'O contrato exige JSON válido e campo ID no tipo esperado. Entrada inválida ou campo obrigatório ausente produz diagnóstico, sem ser convertido silenciosamente em uma identidade vazia.'},
      practice:'Com Leapwork instalado, use seu template atual e apenas uma transformação pequena. Valide entradas normais e inválidas antes de integrar.',
      quiz:[q('O template de qualquer versão é garantido em outra?','Não; confira a instalação e as referências.','Sim, toda assinatura é idêntica para sempre.','A documentação registra mudanças de ambiente.'),q('O que deve acontecer com JSON inválido no exemplo?','Um resultado de erro definido pelo contrato.','Aprovação automática com ID vazio.','A ausência de dado obrigatório não comprova sucesso.')],docs:[ref('logic','c-sharp-code'),['Notas 2026.3 · runtime','release-notes/leapwork-flow-major-release-2026-3']]
    },
    {
      slug:'dados-laboratorio',title:'Laboratório: validar, calcular e registrar',topic:'pratica',read:'15 min',lab:true,
      description:'Use quatro registros fictícios para acompanhar entrada, validação e cálculo, com resultados esperados disponíveis para conferência.',
      objectives:['Aplicar um contrato de entrada explícito.','Acompanhar cada registro até o resultado.','Separar o simulador local de uma execução no Leapwork.'],
      concepts:[['Dados autorais','Os arquivos e a regra desta aula foram criados para estudo. Não são os enunciados dos exercícios oficiais e não foram executados no Leapwork.'],['Regra verificável','Quantidade deve ser um inteiro positivo; preço usa vírgula decimal sem separador de milhar; grupo BASICO recebe 5% e PREMIUM recebe 10% de desconto. Entrada inválida é rejeitada antes de calcular.'],['Cálculo em centavos','O laboratório calcula em centavos e arredonda pontos médios para o par mais próximo. Isso explicita a política didática; o fluxo real precisa validar conversão, unidades e comportamento do bloco.']],
      flow:['Ler registro','Normalizar espaços e grupo','Validar contrato','Calcular em centavos','Registrar por ID'],flowNote:'Simulação autoral executada só no navegador. Ela não cria nem testa um fluxo Leapwork.',
      steps:[ds('data-driven','read-excel','Confira os arquivos de entrada','Baixe a planilha, o CSV e o JSON fictícios. Confira os mesmos quatro IDs e os valores brutos antes de usar o simulador.','O preço da planilha é texto de entrada para estudar conversão; não presuma que vírgula será interpretada igualmente em todo ambiente.',true),ds('logic','change-text','Aplique apenas a normalização permitida','Remova espaços externos do nome e normalize o grupo para maiúsculas. Valide quantidade e preço antes de calcular.','Quantidade zero é inválida neste contrato e deve gerar uma rejeição explicada.'),ds('logic','calculate','Calcule e compare com a expectativa','Multiplique quantidade por preço em centavos e aplique o percentual do grupo. Use a política de ponto médio para o par; compare com o arquivo de resultados esperados.','Os dados incluem um valor pequeno que expõe a política de arredondamento.',true),ds('data-driven','write-excel','Planeje o registro no Leapwork','No programa, escreva por ID o status, os valores e o motivo. Conclua apenas quando todos os registros tiverem um resultado explicado e confira Not read e Not written.','Conferir o simulador não substitui executar e verificar o fluxo real.')],
      pitfalls:[['Simulação apresentada como execução','O laboratório demonstra uma regra local, sem acesso ao Leapwork.'],['Rejeição esperada confundida com defeito','O registro inválido deve ser rejeitado; isso é a resposta correta do contrato de entrada.']],
      exercise:{title:'Confira os quatro registros',tasks:['Preveja quais entradas serão aceitas.','Calcule os totais em centavos.','Compare com os resultados esperados e explique cada rejeição.'],answer:'IDs 001, 002 e 004 são aceitos; 003 é rejeitado por quantidade zero. Os totais são 3781, 3375 e 10 centavos. O último caso usa 9,5 centavos antes do arredondamento para o par, resultando em 10.'},
      practice:'Quando tiver Leapwork, reproduza a regra usando uma cópia dos arquivos e compare cada resultado por ID. Valide a conversão de preços e o arredondamento separadamente.',
      quiz:[q('A rejeição de quantidade zero é o resultado correto deste contrato?','Sim; ela é um caso negativo esperado.','Não, todo registro deve ser aceito para o teste passar.','O resultado correto depende da regra do caso.'),q('O simulador comprova que um fluxo Leapwork foi executado?','Não; ele roda apenas no navegador.','Sim, cria um Agent automaticamente.','A execução no programa continua sendo uma etapa de prática futura.')],docs:[ref('data-driven','read-excel'),ref('logic','change-text'),ref('logic','calculate'),ref('logic','compare'),ref('data-driven','write-excel')]
    }
  ];
  d.module3Topics=[['fontes','Fontes e saída de dados'],['logica','Lógica e transformação'],['estado','Variáveis, datas e geradores'],['apoio','Apoio e extensões'],['pratica','Laboratório de integração']];
  lessons.forEach((l,i)=>{
    l.module=3;l.number=String(i+1).padStart(2,'0');l.group=d.module3Topics.find(t=>t[0]===l.topic)[1];l.sourceKind=l.video?'video':'documentation';
    l.quiz.forEach((question,j)=>{if((i+j)%2){question.options.reverse();question.correct=1;}});
    d.lessons.push(l);
  });
  d.module3Rows=[{id:'001',nome:' Ana Lima ',quantidade:'2',preco:'19,90',grupo:' basico '},{id:'002',nome:'Bruno Reis',quantidade:'3',preco:'12,50',grupo:'PREMIUM'},{id:'003',nome:'Carla Melo',quantidade:'0',preco:'10,00',grupo:'BASICO'},{id:'004',nome:'Davi Luz',quantidade:'1',preco:'0,10',grupo:'BASICO'}];
  d.module3Downloads=[['Planilha de entradas fictícias','assets/examples/modulo3-entradas.xlsx'],['CSV de entradas fictícias','assets/examples/modulo3-entradas.csv'],['Resposta JSON fictícia','assets/examples/modulo3-resposta.json'],['Resultados esperados · CSV','assets/examples/modulo3-esperados.csv'],['Modelo de relatório · Excel','assets/examples/modulo3-resultados.xlsx']];
  d.glossary.push(['Data-driven','Orientado a dados','Um roteiro recebe diferentes conjuntos de entradas, com uma expectativa verificável para cada um.'],['ODBC','Conexão com banco','Interface usada pelo bloco Database, configurada no ambiente em que o caso é executado.'],['Scope','Escopo','Define onde e por quanto tempo um valor de variável é compartilhado.'],['Default value','Valor padrão','Fallback para a leitura de uma variável ausente; não prova que ela tenha sido inicializada.'],['No match','Sem correspondência','Saída de Switch para um Input que não corresponde a nenhum caso.'],['Arredondamento para o par','Política de ponto médio','Em empates de arredondamento, escolhe a representação cujo último dígito retido é par.']);
  d.lessons.sort((a,b)=>a.module-b.module||Number(a.number)-Number(b.number));
})();
